import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - even Zeus's thunderbolts need proper wiring
const mockCart = {
  items: [{ id: '1', name: 'Golden Fleece', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn()
};

const mockPayment = {
  processPayment: vi.fn()
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

describe('Checkout - The Complete Forge', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Golden Fleece', price: 99.99 }];
  });

  describe('Happy Path - Bronze Tempered True', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-123' });

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Olympus Lane');
      await user.type(screen.getByLabelText(/city/i), 'Athens');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Hephaestus');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/golden fleece/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-123')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  describe('Validation - Testing the Metal', () => {
    it('displays shipping validation errors for empty fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates credit card number is 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment
      await fillShippingForm(user);
      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit/i)).toBeInTheDocument();
    });
  });

  describe('Error States - When the Forge Falters', () => {
    it('displays payment error and allows retry', async () => {
      const user = userEvent.setup();
      mockPayment.processPayment
        .mockRejectedValueOnce(new Error('Card declined'))
        .mockResolvedValueOnce({ orderId: 'ORD-456' });

      render(<Checkout />);
      await completeToReview(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByText(/card declined/i)).toBeInTheDocument();

      // Retry succeeds
      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  describe('Loading States - The Anvil Strikes', () => {
    it('disables buttons and shows loading during submission', async () => {
      const user = userEvent.setup();
      let resolvePayment: (value: { orderId: string }) => void;
      mockPayment.processPayment.mockImplementation(() => 
        new Promise(r => { resolvePayment = r; })
      );

      render(<Checkout />);
      await completeToReview(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();

      resolvePayment!({ orderId: 'ORD-789' });
    });
  });

  describe('Edge Cases - The Unusual Alloys', () => {
    it('shows empty cart message when no items', () => {
      mockCart.items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Accessibility - Worthy of All Heroes', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('announces validation errors to screen readers', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const alerts = screen.getAllByRole('alert');
      expect(alerts.length).toBeGreaterThan(0);
    });
  });
});

// Helpers - Tools of the Trade
async function fillShippingForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/street address/i), '123 Test St');
  await user.type(screen.getByLabelText(/city/i), 'Test City');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '12345');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReview(user: ReturnType<typeof userEvent.setup>) {
  await fillShippingForm(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Test User');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
